n=17; center=8
grid=[]
for r in range(n):
    row=[0]*n
    if r<=center:
        for c in {center-r,center+r}:
            row[c]=2
    lo=max(0,center-r); hi=min(n-1,center+r)
    phase=(r-2)%4
    for c in range(lo,hi+1):
        if c%4==phase and row[c]==0:
            row[c]=1
    grid.append(row)
import json
print(json.dumps(grid,separators=(',',':')))

